<template>
	<ion-page>
		<ion-content :fullscreen="true">
			<FormView
				v-if="formFields.data"
				doctype="Attendance Request"
				v-model="attendanceRequest"
				:isSubmittable="true"
				:fields="formFields.data"
				:id="props.id"
				@validateForm="validateForm"
			/>
		</ion-content>
	</ion-page>
</template>

<script setup>
import { IonPage, IonContent } from "@ionic/vue"
import { createResource } from "frappe-ui"
import { ref, watch, inject, onMounted } from "vue"
import { useRoute } from "vue-router"

import FormView from "@/components/FormView.vue"

const employee = inject("$employee")
const __ = inject("$translate")
const route = useRoute()

const props = defineProps({
	id: {
		type: String,
		required: false,
	},
})

// reactive object to store form data
const attendanceRequest = ref({})

onMounted(() => {
	if (props.id) return
	const q = route.query || {}
	attendanceRequest.value = {
		...attendanceRequest.value,
		status: "Open",
		employee: employee.data?.name,
	}
	if (q.prefill === "1" && q.from_date) {
		attendanceRequest.value = {
			...attendanceRequest.value,
			from_date: String(q.from_date),
			to_date: String(q.to_date || q.from_date),
		}
	}
})

// get form fields
const formFields = createResource({
	url: "hrms.api.get_doctype_fields",
	params: { doctype: "Attendance Request" },
	auto: true,
	transform(data) {
		const fields = props.id ? data : data.filter(
			(field) =>
				![
					"employee",
					"employee_name",
					"status",
					"company",
					"custom_rejection_reason",
				].includes(field.fieldname)
		)
		return fields.map((field) =>
			field.fieldname === "explanation"
				? {
						...field,
						reqd: 1,
						label: __("Reason / Explanation"),
						placeholder: __("Explain why this attendance request is needed"),
					}
				: field
		)
	},
})

// form scripts
watch(
	() => attendanceRequest.value.employee,
	(employee_id) => {
		if (props.id && employee_id !== employee.data.name) {
			// if employee is not the current user, set form as read only
			setFormReadOnly()
		}
	}
)

watch(
	() => attendanceRequest.value.from_date,
	(from_date) => {
		if (!attendanceRequest.value.to_date) {
			attendanceRequest.value.to_date = from_date
		}
	}
)

watch(
	() => [attendanceRequest.value.from_date, attendanceRequest.value.to_date],
	([from_date, to_date]) => {
		validateDates(from_date, to_date)
	}
)

watch(
	() => attendanceRequest.value.half_day,
	(half_day) => {
		const half_day_date = formFields.data.find((field) => field.fieldname === "half_day_date")
		half_day_date.hidden = !half_day
	}
)

// helper functions
function setFormReadOnly() {
	formFields.data.map((field) => (field.read_only = true))
}

function validateDates(from_date, to_date) {
	if (!(from_date && to_date)) return

	const error_message = from_date > to_date ? __("To Date cannot be before From Date") : ""

	const from_date_field = formFields.data.find((field) => field.fieldname === "from_date")
	from_date_field.error_message = error_message
}

function validateForm() {
	attendanceRequest.value.employee = employee.data.name
	if (!attendanceRequest.value.status) {
		attendanceRequest.value.status = "Open"
	}
}
</script>
